#include <lua.h>
#include <lauxlib.h>
#include <lualib.h>

/* Minimal state lifecycle pattern; handle errors in production code. */
lua_State *L = luaL_newstate();
if (L != NULL) {
    luaL_openlibs(L);
    int status = luaL_dostring(L, "print(\"Hello from Lua\")");
    (void)status;
    lua_close(L);
}
